// Cockpit ITSM public API - runtime core of the C# classes generated by CIPAT
// (Cockpit ITSM Public API Toolkit). .NET 6+, no dependency (HttpClient,
// System.Text.Json.Nodes).
//
// Maintained by hand, embedded in CIPAT and written next to each generated class:
// do not edit a copy, it is replaced when it differs from the generator's version.
//
// - OAuth 2.0 token (client_credentials, multipart/form-data, scope public-api),
//   renewed before expiry and once more on a 401 response (thread-safe);
// - HTTP: HttpClient, given to the constructor or created (proxy and certificates
//   of the system);
// - paged lists: every page read, items merged and truncated to
//   totalNumberOfElements (FetchAllPagesAsync);
// - conversion helpers used by the generated classes (missing or null = null).

#nullable enable

using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Threading;
using System.Threading.Tasks;

namespace CockpitItsm
{
    /// <summary>Error of a Cockpit ITSM call: HTTP status (0 = network error or invalid response) and response body.</summary>
    public class CockpitItsmException : Exception
    {
        public int StatusCode { get; }
        public string Response { get; }

        public CockpitItsmException(int statusCode, string message, string? response = null, Exception? inner = null)
            : base(message, inner)
        {
            StatusCode = statusCode;
            Response = response ?? "";
        }
    }

    /// <summary>Token, HTTP calls and paging. The generated class inherits from it.</summary>
    public class CockpitItsmCore : IDisposable
    {
        private const int DefaultPageSize = 500;
        private static readonly TimeSpan TokenMargin = TimeSpan.FromSeconds(60);

        private readonly HttpClient _http;
        private readonly bool _ownsHttp;
        private readonly SemaphoreSlim _tokenLock = new SemaphoreSlim(1, 1);
        private bool _saas;
        private string _tenant;
        private string _clientId;
        private string _clientSecret;
        private string _token = "";
        private DateTimeOffset _tokenExpiry = DateTimeOffset.MinValue;
        private int _pageSize = DefaultPageSize;

        /// <param name="saas">true: https://{tenant}.cockpit-itsm.com - false: https://{tenant}
        /// (an on-premise tenant given with its scheme, e.g. http://host:8080, is used as is)</param>
        /// <param name="tenant">Tenant name (SaaS) or host name (on premise)</param>
        /// <param name="clientId">OAuth 2.0 client id (scope public-api)</param>
        /// <param name="clientSecret">OAuth 2.0 client secret</param>
        /// <param name="httpClient">HttpClient used for every request (proxy, certificates...); created if null</param>
        public CockpitItsmCore(bool saas, string tenant, string clientId, string clientSecret, HttpClient? httpClient = null)
        {
            _saas = saas;
            _tenant = tenant ?? "";
            _clientId = clientId ?? "";
            _clientSecret = clientSecret ?? "";
            _ownsHttp = httpClient == null;
            _http = httpClient ?? new HttpClient { Timeout = TimeSpan.FromSeconds(60) };
        }

        /// <summary>Releases the HttpClient created by the constructor (not the one given to it).</summary>
        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!disposing) return;
            _tokenLock.Dispose();
            if (_ownsHttp) _http.Dispose();
        }

        // ------------------------------------------------------------------ settings (changing them discards the token)

        public bool SaaS { get => _saas; set { _saas = value; ClearToken(); } }
        public string Tenant { get => _tenant; set { _tenant = value ?? ""; ClearToken(); } }
        public string ClientId { get => _clientId; set { _clientId = value ?? ""; ClearToken(); } }
        public string ClientSecret { get => _clientSecret; set { _clientSecret = value ?? ""; ClearToken(); } }

        /// <summary>Page size of the paged lists (API maximum: 500).</summary>
        public int PageSize { get => _pageSize; set => _pageSize = value > 0 ? value : DefaultPageSize; }

        /// <summary>HTTP status of the last call.</summary>
        public int LastStatus { get; private set; }

        public static string MakeBaseUrl(bool saas, string tenant)
        {
            string result = (tenant ?? "").Trim().TrimEnd('/');
            if (saas) return "https://" + result + ".cockpit-itsm.com";
            return result.Contains("://") ? result : "https://" + result;
        }

        public string BaseUrl => MakeBaseUrl(_saas, _tenant);

        // ------------------------------------------------------------------ token

        public string AccessToken => _token;

        /// <summary>Expiry of the token, 60 s before the server's one.</summary>
        public DateTimeOffset TokenExpiry => _tokenExpiry;

        public bool IsTokenValid => _token.Length > 0 && DateTimeOffset.UtcNow < _tokenExpiry;

        public void ClearToken()
        {
            _token = "";
            _tokenExpiry = DateTimeOffset.MinValue;
        }

        /// <summary>Token obtained elsewhere (shared between instances).</summary>
        public void SetToken(string token, DateTimeOffset expiry)
        {
            _token = token ?? "";
            _tokenExpiry = expiry;
        }

        /// <summary>POST /oauth2/token (multipart/form-data, client credentials, scope public-api).</summary>
        public async Task AuthenticateAsync(CancellationToken cancellationToken = default)
        {
            ClearToken();
            if (_tenant.Length == 0 || _clientId.Length == 0 || _clientSecret.Length == 0)
                throw new CockpitItsmException(0, "Cockpit ITSM: tenant, ClientId and ClientSecret are required");
            // multipart/form-data written as by the other cores (quoted names, no content
            // type per part)
            string boundary = "----CockpitItsm" + Guid.NewGuid().ToString("N");
            var sb = new StringBuilder();
            foreach (var (name, value) in new[] { ("grant_type", "client_credentials"), ("client_id", _clientId),
                ("client_secret", _clientSecret), ("scope", "public-api") })
            {
                sb.Append("--").Append(boundary).Append("\r\nContent-Disposition: form-data; name=\"").Append(name)
                    .Append("\"\r\n\r\n").Append(value).Append("\r\n");
            }
            sb.Append("--").Append(boundary).Append("--\r\n");
            using var form = new StringContent(sb.ToString(), Encoding.UTF8);
            form.Headers.ContentType = MediaTypeHeaderValue.Parse("multipart/form-data; boundary=" + boundary);
            var (status, text) = await SendAsync(HttpMethod.Post, BaseUrl + "/oauth2/token", form, false, cancellationToken)
                .ConfigureAwait(false);
            LastStatus = status;
            if (status != 200) throw Error(status, text);
            var obj = AsObj(Parse(text));
            string? token = ToStr(obj?["access_token"]);
            if (string.IsNullOrEmpty(token))
                throw new CockpitItsmException(status, "Cockpit ITSM: no token in the response", text);
            var lifetime = TimeSpan.FromSeconds(ToLong(obj?["expires_in"]) ?? 3600);
            if (lifetime > TokenMargin + TokenMargin) lifetime -= TokenMargin;
            _token = token!;
            _tokenExpiry = DateTimeOffset.UtcNow + lifetime;
        }

        private async Task EnsureTokenAsync(string usedToken, CancellationToken cancellationToken)
        {
            await _tokenLock.WaitAsync(cancellationToken).ConfigureAwait(false);
            try
            {
                // Another call may have renewed it in the meantime
                if (!IsTokenValid || _token == usedToken) await AuthenticateAsync(cancellationToken).ConfigureAwait(false);
            }
            finally
            {
                _tokenLock.Release();
            }
        }

        // ------------------------------------------------------------------ calls

        private async Task<(int Status, string Text)> SendAsync(HttpMethod method, string url, HttpContent? content,
            bool auth, CancellationToken cancellationToken)
        {
            using var request = new HttpRequestMessage(method, url) { Content = content };
            request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
            if (auth) request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _token);
            try
            {
                using var response = await _http.SendAsync(request, cancellationToken).ConfigureAwait(false);
                string text = await response.Content.ReadAsStringAsync(cancellationToken).ConfigureAwait(false);
                return ((int)response.StatusCode, text);
            }
            catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
            {
                throw;
            }
            catch (Exception e)
            {
                throw new CockpitItsmException(0, "Cockpit ITSM: " + e.GetType().Name + " - " + e.Message + " (" + url + ")", "", e);
            }
        }

        private static StringContent? Content(string? body, HttpMethod method)
        {
            if (body == null && method != HttpMethod.Post && method != HttpMethod.Put && method != HttpMethod.Patch) return null;
            return new StringContent(body ?? "", Encoding.UTF8, "application/json");
        }

        /// <summary>Authenticated call; authenticates again once on 401; throws CockpitItsmException on a non-2xx status.</summary>
        /// <param name="method">GET, POST, PUT, DELETE...</param>
        /// <param name="pathQuery">e.g. "/api/end-users/12"</param>
        /// <param name="body">text sent as is (JSON or plain text), null = none</param>
        /// <returns>raw response</returns>
        public async Task<string> CallAsync(string method, string pathQuery, string? body = null,
            CancellationToken cancellationToken = default)
        {
            var httpMethod = new HttpMethod(method);
            string usedToken = _token;
            if (!IsTokenValid) await EnsureTokenAsync(usedToken, cancellationToken).ConfigureAwait(false);
            usedToken = _token;
            var (status, text) = await SendAsync(httpMethod, BaseUrl + pathQuery, Content(body, httpMethod), true,
                cancellationToken).ConfigureAwait(false);
            if (status == (int)HttpStatusCode.Unauthorized)
            {
                await EnsureTokenAsync(usedToken, cancellationToken).ConfigureAwait(false);
                (status, text) = await SendAsync(httpMethod, BaseUrl + pathQuery, Content(body, httpMethod), true,
                    cancellationToken).ConfigureAwait(false);
            }
            LastStatus = status;
            if (status < 200 || status > 299) throw Error(status, text);
            return text;
        }

        /// <summary>Parsed JSON response, null for an empty response.</summary>
        public async Task<JsonNode?> CallJsonAsync(string method, string pathQuery, string? body = null,
            CancellationToken cancellationToken = default)
        {
            return Parse(await CallAsync(method, pathQuery, body, cancellationToken).ConfigureAwait(false));
        }

        /// <summary>Items ("content") of every page of a paged list, truncated to totalNumberOfElements.</summary>
        /// <param name="pagePath">dotted path of the {page, pageSize} object in the body ("" = the body itself)</param>
        public async Task<JsonArray> FetchAllPagesAsync(string method, string pathQuery, JsonObject? body, string pagePath,
            CancellationToken cancellationToken = default)
        {
            var root = body ?? new JsonObject();
            var pageObj = root;
            if (!string.IsNullOrEmpty(pagePath))
            {
                foreach (string name in pagePath.Split('.'))
                {
                    if (pageObj[name] is not JsonObject child)
                    {
                        child = new JsonObject();
                        pageObj[name] = child;
                    }
                    pageObj = child;
                }
            }
            var result = new JsonArray();
            int page = 0;
            long totalPages = 1;
            long total = -1;
            do
            {
                pageObj["page"] = page;
                pageObj["pageSize"] = _pageSize;
                var resp = AsObj(await CallJsonAsync(method, pathQuery, root.ToJsonString(), cancellationToken).ConfigureAwait(false))
                    ?? throw new CockpitItsmException(0, "Cockpit ITSM: invalid paged response");
                if (page == 0)
                {
                    totalPages = ToLong(resp["totalNumberOfPages"]) ?? 1;
                    total = ToLong(resp["totalNumberOfElements"]) ?? -1;
                }
                if (resp["content"] is not JsonArray content || content.Count == 0) break;
                foreach (var item in content.ToList())
                {
                    content.Remove(item);
                    result.Add(item);
                }
                page++;
            } while (page < totalPages);
            while (total >= 0 && result.Count > total) result.RemoveAt(result.Count - 1);
            return result;
        }

        private static CockpitItsmException Error(int status, string text)
        {
            string msg = "";
            try
            {
                if (Parse(text) is JsonObject o)
                    msg = new[] { ToStr(o["errorMessage"]), ToStr(o["error_description"]), ToStr(o["error"]) }
                        .FirstOrDefault(s => !string.IsNullOrWhiteSpace(s)) ?? "";
            }
            catch (CockpitItsmException)
            {
                // not JSON
            }
            if (msg.Length == 0)
            {
                msg = (text ?? "").Trim();
                if (msg.Length > 300) msg = string.Concat(msg.AsSpan(0, 300), "...");
            }
            return new CockpitItsmException(status, "Cockpit ITSM: HTTP error " + status + " - " + msg, text);
        }

        // ------------------------------------------------------------------ URL helpers

        public static string UrlEncode(object? value) =>
            Uri.EscapeDataString(Convert.ToString(value, CultureInfo.InvariantCulture) ?? "");

        /// <summary>Query parameter; null not sent, a list sent as repeated keys.</summary>
        public static void AddQuery(List<KeyValuePair<string, string>> query, string name, object? value)
        {
            switch (value)
            {
                case null:
                    return;
                case string s:
                    query.Add(new KeyValuePair<string, string>(name, s));
                    return;
                case IEnumerable items:
                    foreach (object? item in items) AddQuery(query, name, item);
                    return;
                case bool b:
                    query.Add(new KeyValuePair<string, string>(name, b ? "true" : "false"));
                    return;
                case DateTimeOffset d:
                    query.Add(new KeyValuePair<string, string>(name, FormatDateTime(d)));
                    return;
                case DateOnly d:
                    query.Add(new KeyValuePair<string, string>(name, FormatDate(d)));
                    return;
                case double d:
                    query.Add(new KeyValuePair<string, string>(name, d.ToString("R", CultureInfo.InvariantCulture)));
                    return;
                default:
                    query.Add(new KeyValuePair<string, string>(name, Convert.ToString(value, CultureInfo.InvariantCulture) ?? ""));
                    return;
            }
        }

        /// <summary>"" or "?a=1&amp;b=2"</summary>
        public static string QueryString(List<KeyValuePair<string, string>> query)
        {
            if (query.Count == 0) return "";
            return "?" + string.Join("&", query.Select(kv => Uri.EscapeDataString(kv.Key) + "=" + Uri.EscapeDataString(kv.Value)));
        }

        // ------------------------------------------------------------------ dates

        /// <summary>ISO 8601 date-time (Z, +hh:mm, +hhmm, no offset = UTC); null if invalid.</summary>
        public static DateTimeOffset? ParseDateTime(string? value)
        {
            if (value == null || value.Trim().Length < 10) return null;
            string s = value.Trim();
            if (s.Length > 5 && (s[s.Length - 5] == '+' || s[s.Length - 5] == '-') && s.Substring(s.Length - 4).All(char.IsDigit)
                && s.Contains('T'))
                s = string.Concat(s.AsSpan(0, s.Length - 2), ":", s.AsSpan(s.Length - 2));
            return DateTimeOffset.TryParse(s, CultureInfo.InvariantCulture,
                DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out var result) ? result : null;
        }

        /// <summary>Date only "yyyy-mm-dd" (time and offset ignored); null if invalid.</summary>
        public static DateOnly? ParseDate(string? value)
        {
            if (value == null || value.Trim().Length < 10) return null;
            return DateOnly.TryParseExact(value.Trim().Substring(0, 10), "yyyy-MM-dd", CultureInfo.InvariantCulture,
                DateTimeStyles.None, out var result) ? result : null;
        }

        /// <summary>UTC ISO 8601 with milliseconds ("2026-11-03T14:30:00.000Z").</summary>
        public static string FormatDateTime(DateTimeOffset value) =>
            value.UtcDateTime.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'", CultureInfo.InvariantCulture);

        public static string FormatDate(DateOnly value) => value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);

        // ------------------------------------------------------------------ JSON: reading (null if missing, null or invalid)

        /// <summary>JSON text -> node; null for an empty text.</summary>
        public static JsonNode? Parse(string? text)
        {
            if (string.IsNullOrWhiteSpace(text)) return null;
            try
            {
                return JsonNode.Parse(text);
            }
            catch (JsonException e)
            {
                throw new CockpitItsmException(0, "Invalid JSON response: " + e.Message, text, e);
            }
        }

        public static JsonObject? AsObj(JsonNode? node) => node as JsonObject;

        public static JsonArray? AsArr(JsonNode? node) => node as JsonArray;

        /// <summary>Text of a JSON string response ("abc" -> abc), other text unchanged.</summary>
        public static string? Unquote(string? text)
        {
            if (text == null) return null;
            string s = text.Trim();
            if (s.Length >= 2 && s[0] == '"' && s[s.Length - 1] == '"')
            {
                try
                {
                    return JsonNode.Parse(s)?.GetValue<string>() ?? s;
                }
                catch (Exception)
                {
                    return text;
                }
            }
            return text;
        }

        private static bool TryValue<T>(JsonNode? node, out T? value)
        {
            if (node is JsonValue v && v.TryGetValue(out T? result))
            {
                value = result;
                return true;
            }
            value = default;
            return false;
        }

        public static string? ToStr(JsonNode? node)
        {
            if (node == null) return null;
            if (TryValue(node, out string? s)) return s;
            if (node is JsonValue v && v.TryGetValue(out JsonElement e) && e.ValueKind == JsonValueKind.String) return e.GetString();
            return node.ToJsonString();
        }

        public static double? ToDouble(JsonNode? node)
        {
            if (TryValue(node, out double d)) return d;
            string? s = node is JsonValue ? ToStr(node) : null;
            return double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out d) ? d : null;
        }

        public static long? ToLong(JsonNode? node)
        {
            if (TryValue(node, out long l)) return l;
            double? d = ToDouble(node);
            return d.HasValue ? (long)d.Value : null;
        }

        public static int? ToInt(JsonNode? node)
        {
            long? l = ToLong(node);
            return l.HasValue ? (int)l.Value : null;
        }

        public static bool? ToBool(JsonNode? node)
        {
            if (TryValue(node, out bool b)) return b;
            string? s = node is JsonValue ? ToStr(node) : null;
            if (s != null) return s.Trim().Equals("true", StringComparison.OrdinalIgnoreCase);
            return null;
        }

        public static DateTimeOffset? ToDateTime(JsonNode? node) => node is JsonValue ? ParseDateTime(ToStr(node)) : null;

        public static DateOnly? ToDate(JsonNode? node) => node is JsonValue ? ParseDate(ToStr(node)) : null;

        /// <summary>JSON text of a value (raw members).</summary>
        public static string? ToRaw(JsonNode? node) => node?.ToJsonString();

        /// <summary>Converted items of a JSON array (null or invalid items dropped); null if the array is missing.</summary>
        public static List<T>? ListOf<T>(JsonNode? node, Func<JsonNode?, T?> conv) where T : class
        {
            if (node is not JsonArray arr) return null;
            var result = new List<T>(arr.Count);
            foreach (var item in arr)
            {
                T? v = item == null ? null : conv(item);
                if (v != null) result.Add(v);
            }
            return result;
        }

        /// <summary>ListOf for value types (numbers, booleans, dates).</summary>
        public static List<T>? ListOfValues<T>(JsonNode? node, Func<JsonNode?, T?> conv) where T : struct
        {
            if (node is not JsonArray arr) return null;
            var result = new List<T>(arr.Count);
            foreach (var item in arr)
            {
                T? v = item == null ? null : conv(item);
                if (v.HasValue) result.Add(v.Value);
            }
            return result;
        }

        // ------------------------------------------------------------------ JSON: writing (null values are not written)

        /// <summary>JSON array of the converted items of a list.</summary>
        public static JsonArray ArrayOf<T>(IEnumerable<T>? items, Func<T, JsonNode?> conv)
        {
            var result = new JsonArray();
            if (items != null)
                foreach (T item in items) result.Add(item == null ? null : conv(item));
            return result;
        }

        public static JsonNode? FromValue(string? value) => value == null ? null : JsonValue.Create(value);
        public static JsonNode? FromValue(long? value) => value.HasValue ? JsonValue.Create(value.Value) : null;
        public static JsonNode? FromValue(int? value) => value.HasValue ? JsonValue.Create(value.Value) : null;
        public static JsonNode? FromValue(double? value) => value.HasValue ? JsonValue.Create(value.Value) : null;
        public static JsonNode? FromValue(bool? value) => value.HasValue ? JsonValue.Create(value.Value) : null;
        public static JsonNode? FromValue(DateTimeOffset? value) => value.HasValue ? JsonValue.Create(FormatDateTime(value.Value)) : null;
        public static JsonNode? FromValue(DateOnly? value) => value.HasValue ? JsonValue.Create(FormatDate(value.Value)) : null;

        public static void Put(JsonObject obj, string name, JsonNode? value)
        {
            if (value != null) obj[name] = value;
        }

        /// <summary>Raw member: JSON text inserted as a value.</summary>
        public static void PutRaw(JsonObject obj, string name, string? json)
        {
            if (!string.IsNullOrWhiteSpace(json)) obj[name] = JsonNode.Parse(json);
        }
    }
}
